function tick() {
  requestAnimationFrame(tick);
  const dt = clock.getDelta() * timeScale;

  ninja.position.z -= speed * dt;   // move
  for (const o of obstacles) {
    if (o.z > ninja.z + 6) recycle(o);  // reuse
    if (hits(o, ninja)) gameOver();     // collide
  }
  renderer.render(scene, camera);       // draw
}

function autoPilot() {
  const near = nearestObstacleAhead(16);
  if (!near) return;

  if (near.type === 'rock' && grounded)
    jump();                  // jump the rock
  else
    targetLane = openLane();  // walls need a dodge
}
